SELECT EXISTS (
SELECT 1 FROM target_product_judgement WHERE mydata_trade_id = #{mydataTradeId}
)

SELECT j.judgement_id AS judgementId, c.name AS customerName, j.stock_type AS stockType, j.fund_name AS fundName, j.ticker AS ticker, j.is_target AS isTarget, j.foreign_stock_ratio AS foreignStockRatio, j.inception_date AS inceptionDate, j.trade_type AS tradeType, j.amount AS amount, j.net_buy_amount AS netBuyAmount, j.trade_date AS tradeDate, j.judged_at AS judgedAt FROM target_product_judgement j JOIN customer c ON c.ci_hash = j.ci_hash
AND c.name LIKE CONCAT('%', #{customerName}, '%')
AND j.stock_type = #{stockType}
AND j.is_target = #{isTarget}
AND j.trade_type = #{tradeType}
AND j.trade_type IN ('INHERITANCE', 'GIFT')
AND j.judged_at >= #{judgedAtFrom}
AND j.judged_at < #{judgedAtTo}
ORDER BY j.judged_at DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM target_product_judgement j
JOIN customer c ON c.ci_hash = j.ci_hash


        AND c.name LIKE CONCAT('%', #{customerName}, '%')


        AND j.stock_type = #{stockType}


        AND j.is_target = #{isTarget}


        AND j.trade_type = #{tradeType}


        AND j.trade_type IN ('INHERITANCE', 'GIFT')


        AND j.judged_at >= #{judgedAtFrom}


        AND j.judged_at < #{judgedAtTo}
